/// <summary>
/// Packed query contract member
/// </summary>
/// <param name = "_packedQuery">Packed query</param>
/// <returns>query</returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METSOTobaccoLicUpdateQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Returns the query to be used on the dialog or data service
/// </summary>
/// <returns>Query object after unpacking the serialized data</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Pack/serialize the query 
/// </summary>
/// <param name = "_query">Query to be packed</param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}
